    costPerCup:            num(f['costPerCup']) || 0.50,
    qualityScore:          s5(f['qualityScore']) || 3,
    espressoQualityScore:  f['espressoQualityScore'] != null ? s5(f['espressoQualityScore']) : undefined,
    ecoScore:              s5(f['ecoScore']) || 3,
    ecoRepairScore:        s5(f['ecoRepairScore']) || 3,
    speedScore:            s5(f['speedScore']) || 3,
    varietyScore:          s5(f['varietyScore']) || 3,
    learningCurve:         sel(f['learningCurve']) || 'Medium',
    easeOfUse:             s5(f['easeOfUse']) || 3,
    drinkTypes:            normDrinks(parseList(f['drinkTypes'])),
    effortMatch:           parseList(f['effortMatch']).map(e => EFFORT_TOKEN_MAP[e.toLowerCase().trim()] || e.toLowerCase().trim()),
    coffeeTypeMatch:       parseList(f['coffeeTypeMatch']),
    isEspressoStyle:       !!f['isEspressoStyle'],
    compact:               !!f['compact'],
    sentiment:             f['sentiment']   || '',
    description:           f['description'] || '',
    affiliateBase:         { us: f['buyLinkUS'] || '#', uk: f['buyLinkUK'] || '#', ca: f['buyLinkCA'] || '#', eu: f['buyLinkEU'] || '#', au: f['buyLinkAU'] || '#' },
    features:              parseList(f['features']),
    bundles:               parseList(f['bundles']),
    imageUrl:              null,
    historicLowUSD:        f['historicLowUSD'] != null ? parseFloat(f['historicLowUSD']) : null,
    historicLowGBP:        f['historicLowGBP'] != null ? parseFloat(f['historicLowGBP']) : null,
    historicLowCAD:        f['historicLowCAD'] != null ? parseFloat(f['historicLowCAD']) : null,
    historicLowEUR:        f['historicLowEUR'] != null ? parseFloat(f['historicLowEUR']) : null,
    historicLowAUD:        f['historicLowAUD'] != null ? parseFloat(f['historicLowAUD']) : null,
    historicLowPeriod:     f['historicLowPeriod'] || null,
