function applyExtras(machineList) {
    machineList.forEach(m => {
      if (IMAGE_MAP[m.name]) m.imageUrl = IMAGE_MAP[m.name];
      const extra = machineExtras[m.name];
      if (extra) {
        m.ecoRepairScore = extra.ecoRepairScore;
        if (!m.bundles || m.bundles.length === 0) m.bundles = extra.bundles;
      }
    });
  }


const EFFORT_LEVELS = { 'none': 0, 'minimal': 1, 'moderate': 2, 'hands-on': 3 };
const AUTO_LEVELS   = { 'super': 0, 'auto': 1, 'semi': 2, 'manual': 3 };
const MAINTENANCE_TOLERANCE = { none: 1, light: 2, moderate: 3, high: 4 };
const MACHINE_MAINTENANCE   = { low: 1, medium: 2, high: 4 };
const PRIORITY_SCORE_FIELD  = { speed: 'speedScore', quality: null, eco: 'ecoScore', variety: 'varietyScore' }; // null = computed


function maintenanceScore(m) {
  const tolerance = MAINTENANCE_TOLERANCE[userAnswers.maintenance] || 3;
  const required  = MACHINE_MAINTENANCE[m.maintenanceLevel] || MACHINE_MAINTENANCE[m.maintenance] || 2;
  const gap = required - tolerance; // positive = machine needs more than user wants
  if (gap <= 0) return { pts: 15, ok: true };        // fits or easier
  if (gap === 1) return { pts: 0,  ok: true };        // slight mismatch, neutral
  if (gap === 2) return { pts: -15, ok: false };      // moderate mismatch
  return { pts: -25, ok: false };                      // hard mismatch
}

// Returns the highest relevant quality score among machines that are broadly compatible
// with the user's intent — used to score each machine relative to what's realistically available
function getQualityCeiling(affordable, drinks, effort) {
  const safeD        = Array.isArray(drinks) ? drinks : [];
  const wantsEspresso = safeD.includes('espresso') || safeD.includes('latte');
  const wantsMilk     = safeD.includes('latte');
  const userLevel     = EFFORT_LEVELS[effort] ?? 2;

  const relevant = affordable.filter(m => {
    if (Math.abs((AUTO_LEVELS[m.automationLevel] ?? 2) - userLevel) > 2) return false;
    if (wantsMilk && (!m.milkSystem || m.milkSystem === 'none')) return false;
    const dt = Array.isArray(m.drinkTypes) ? m.drinkTypes : (m.drinkTypes ? String(m.drinkTypes).split(',').map(s=>s.trim()) : []);
    if (wantsEspresso && !dt.includes('espresso') && !m.isEspressoStyle) return false;
    return true;
  });

  const qualityOf = m => (wantsEspresso || wantsMilk)
    ? (m.espressoQualityScore ?? m.qualityScore ?? 0)
    : (m.qualityScore ?? 0);

  return relevant.length > 0 ? Math.max(...relevant.map(qualityOf)) : 0;
}

function scoreMachine(m, qualityCeiling, bestAnnualTCO) {
  let score = 0;
  const reasons = [], misses = [];

  const _toArr = (v) => Array.isArray(v) ? v : (v ? String(v).split(',').map(s=>s.trim()).filter(Boolean) : []);
  const effortMatch     = _toArr(m.effortMatch);
  const coffeeTypeMatch = _toArr(m.coffeeTypeMatch);
  const drinkTypes      = _toArr(m.drinkTypes).map(s => s.toLowerCase().trim());
  const drinks          = Array.isArray(userAnswers.drinks) ? userAnswers.drinks : [];
  const priorities      = Array.isArray(userAnswers.priorities) ? userAnswers.priorities : [];
  const effort          = userAnswers.effort || null;
  const budget          = userAnswers.budget || 0;
  const wantsEspresso   = drinks.includes('espresso') || drinks.includes('latte');
  const wantsMilk       = drinks.includes('latte');
  const wantsDrip       = drinks.includes('drip') || drinks.includes('specialty') || drinks.includes('filter');
  const wantsCold       = drinks.includes('cold');
  const wantsPod        = drinks.includes('pod') || drinks.includes('capsule'); // capsule is legacy alias
  // Normalise pod/capsule in user drinks
  const drinksNorm      = drinks.map(d => d === 'capsule' ? 'pod' : d);

  // ── Hard gates (return null = excluded entirely) ──────────────────────────
  if (getPrice(m) > budget) return null;
  if (effort === 'minimal'  && m.automationLevel === 'manual') return null;
  if (effort === 'none'     && m.automationLevel !== 'super' && m.automationLevel !== 'auto') return null;
  // Hard budget floor: exclude machines below 30% of stated budget (unless budget is very low)
  if (budget >= 150 && getPrice(m) < budget * 0.30) return null;

  // ── Upper price nudge: slight penalty when machine is right at budget ceiling
  if (getPrice(m) > budget * 0.9) score -= 10;
  // ── Lower price nudge: graduated penalty for machines well under budget
  if (budget >= 300 && getPrice(m) < budget * 0.45) score -= 20;
  else if (budget >= 200 && getPrice(m) < budget * 0.55) score -= 10;

  // ── 1. Drink coverage (max 30pts) ─────────────────────────────────────────
  if (drinks.length > 0) {
    const covered = drinks.reduce((sum, d) => {
      if (d === 'latte') {
        if (drinkTypes.includes('latte') && m.milkSystem && m.milkSystem !== 'none') return sum + 1;
        if (m.isEspressoStyle && m.milkSystem && m.milkSystem !== 'none') return sum + 0.5;
        return sum;
      }
      if (drinkTypes.includes(d)) return sum + 1;
      if (d === 'espresso' && m.isEspressoStyle) return sum + 0.5;
      return sum;
    }, 0);
    const pct = covered / drinks.length;
    score += Math.round(pct * 30);
    if (pct >= 0.95) reasons.push('Makes all your drink types');
    else if (pct >= 0.6) reasons.push('Covers most of your drink types');
    else misses.push('Misses some of your drink types');
  }

  if (wantsEspresso && !drinkTypes.includes('espresso') && !m.isEspressoStyle) {
    score -= 30; misses.push('Cannot make espresso');
  }

  // ── 2. Milk system (3-tier, effort-aware) ─────────────────────────────────
  if (wantsMilk) {
    const ms = m.milkSystem || 'none';
    const milkProportion = drinks.filter(d => d === 'latte').length / drinks.length;
    const lowEffort = ['none', 'minimal'].includes(effort);
    const isPod = m.automationLevel === 'auto' && (Array.isArray(m.coffeeTypeMatch) ? m.coffeeTypeMatch : String(m.coffeeTypeMatch).split(',')).map(s=>s.trim()).includes('pods');

    if (ms === 'integrated') {
      score += 25; reasons.push('One-touch milk system');
    } else if (ms === 'auto-frother') {
      score += 18; reasons.push('Auto milk frother');
    } else if (ms === 'manual-wand') {
      score += 5;
      if (lowEffort) { score -= 30; misses.push('Manual milk steaming is more effort than you wanted'); }
    } else if (isPod) {
      // Pod machines with no built-in milk: small penalty only, Aeroccino note added at render time
      score -= 5; reasons.push('Add Aeroccino frother for milk drinks');
    } else {
      // Non-pod machines with no milk system: full penalty
      score += drinks.length === 1 ? -35 : milkProportion >= 0.5 ? -30 : -12;
      misses.push('No milk system for milk drinks');
    }

    // Semi-auto workflow penalty for low-effort milk drinkers
    if (lowEffort && m.automationLevel === 'semi') {
      score -= 25; misses.push('Semi-automatic workflow is more hands-on than you wanted');
    }
  }

  if (wantsMilk  && m.automationLevel === 'manual') score -= 25;
  if (!wantsMilk && wantsDrip && ['manual','auto'].includes(m.automationLevel)) score += 10;
  // Extra bonus for manual brewers when user explicitly wants specialty + is hands-on
  if (wantsDrip && drinks.includes('specialty') && effort === 'hands-on' && m.automationLevel === 'manual') score += 15;
  // Cold brew: bonus for machines that support it
  if (wantsCold && drinkTypes.some(d => d.includes('cold'))) { score += 10; reasons.push('Supports cold brew / iced'); }
  // Pod user: bonus for pod machines, penalty for non-pod machines
  if (wantsPod && coffeeTypeMatch.includes('pods')) { score += 15; reasons.push('Compatible with your pods'); }
  if (wantsPod && !coffeeTypeMatch.includes('pods') && !coffeeTypeMatch.includes('any')) { score -= 20; misses.push('Not designed for pods'); }

  // ── 3. Effort / automation fit (asymmetric) ───────────────────────────────
  if (effort && effortMatch.includes(effort)) {
    score += 25; reasons.push('Matches your effort preference');
  } else if (effort) {
    const overshoot = (AUTO_LEVELS[m.automationLevel] ?? 2) - (EFFORT_LEVELS[effort] ?? 2);
    if (overshoot > 0) {
      score -= overshoot * 10;
      if (overshoot >= 2) misses.push('Effort level mismatch');
    } else {
      score += 3; // machine is easier than requested — small credit
    }
  }

  // ── 4. Budget tier expectation ────────────────────────────────────────────
  if (budget >= 1000 && effort !== 'hands-on') {
    if (m.automationLevel === 'manual')           { score -= 25; misses.push('Manual brewer at premium budget'); }
    else if (getPrice(m) < budget * 0.30)         { score -= 10; } // belt-and-suspenders (hard gate already handles most cases)
  }

  // ── 5. Maintenance tolerance ──────────────────────────────────────────────
  const maint = maintenanceScore(m);
  score += maint.pts;
  if (maint.ok) reasons.push('Fits your maintenance tolerance');
  else misses.push('More maintenance than you want');

  // ── 6. Coffee type ────────────────────────────────────────────────────────
  const ct = userAnswers.coffeeType;
  if (ct && ct !== 'any') {
    if (coffeeTypeMatch.includes(ct)) { score += 15; reasons.push('Compatible with your coffee type'); }
    else { score -= 15; misses.push('Not ideal for your coffee type'); }
  }

  // ── 7. Learning curve ─────────────────────────────────────────────────────
  if (effort === 'none' && m.learningCurve === 'High') {
    score -= 15; misses.push('Steep learning curve');
  }

  // ── 8. TCO efficiency (relative to best relevant machine) ─────────────────
  const { fullAnnualTCO } = calcTCO(m);
  if (bestAnnualTCO > 0) {
    const ratio = 1 - ((fullAnnualTCO - bestAnnualTCO) / Math.max(bestAnnualTCO, 1));
    if      (ratio >= 0.8) { score += 12; reasons.push('Excellent annual running cost'); }
    else if (ratio >= 0.5)   score += 6;
    else if (ratio <  0)   { score -= 10; misses.push('High annual running cost'); }
  }

  // ── 9. Quality ceiling ────────────────────────────────────────────────────
  const relQ = (wantsMilk || wantsEspresso)
    ? (m.espressoQualityScore ?? m.qualityScore ?? 0)
    : (m.qualityScore ?? 0);
  const qualityGap = qualityCeiling - relQ;
  if (qualityGap === 0) { score += 10; reasons.push('Top cup quality for your budget'); }
  else { score -= qualityGap * 5; if (qualityGap >= 2) misses.push('Lower cup quality than alternatives'); }

  // ── 10. Priority bonuses ──────────────────────────────────────────────────
  const weights = [20, 12, 6];
  priorities.forEach((p, idx) => {
    const w = weights[idx] || 4;
    const matched =
      (p === 'quality'  && relQ >= 4) ||
      (p === 'speed'    && m.speedScore >= 4) ||
      (p === 'eco'      && ((m.ecoScore || 0) >= 4 || (m.ecoRepairScore || 0) >= 4)) ||
      (p === 'variety'  && m.varietyScore >= 4) ||
      (p === 'compact'  && (m.widthInches != null ? m.widthInches < 10 : m.compact)) ||
      (p === 'cost'     && fullAnnualTCO <= bestAnnualTCO * 1.3);
    if (matched) {
      score += w;
      if (idx === 0) reasons.push(`Strong on your top priority: ${p}`);
    } else {
      if (idx === 0) { score -= Math.round(w * 0.4); misses.push(`Weak on top priority: ${p}`); }
    }
    if (p === 'quality' && idx <= 1 && qualityGap > 0) score -= qualityGap * 6;
  });

  // ── 11. Volume & temperature ──────────────────────────────────────────────
  const cups   = userAnswers.cups || 2;
  const tempImp = userAnswers.tempImportance;
  if (cups >= 4 && ['auto','super'].includes(m.automationLevel)) score += 8;
  if (cups >= 4 && m.automationLevel === 'manual') score -= 10;
  if (cups <= 2 && m.automationLevel === 'super' && !wantsMilk) score -= 5;
  if (tempImp === 'very' && m.brewTempMax >= 93) { score += 8; reasons.push('Brews at high temperature'); }
  if (tempImp === 'very' && m.brewTempMax < 90)  { score -= 10; misses.push('Brews at lower temperature'); }

  return { score: Math.min(99, Math.max(0, score)), reasons, misses };
}


// Ranking block from showResults(): returns the list the quiz would display.
function rank(machines) {
  const budget        = userAnswers.budget || 9999;
    const drinks        = Array.isArray(userAnswers.drinks) ? userAnswers.drinks : [];
    const wantsMilk     = drinks.includes('latte');
    const wantsEsp      = drinks.includes('espresso') || wantsMilk;
    const affordable    = machines.filter(m => getPrice(m) <= budget);
    const qualityCeiling = getQualityCeiling(affordable, drinks, userAnswers.effort);

    // TCO baseline from relevant machines only (same intent category), fallback to all affordable
    const relevantForTCO = affordable.filter(m => {
      if (wantsMilk && (!m.milkSystem || m.milkSystem === 'none')) return false;
      if (wantsEsp  && Array.isArray(m.drinkTypes) && !m.drinkTypes.includes('espresso') && !m.isEspressoStyle) return false;
      return true;
    });
    const bestAnnualTCO = Math.min(
      ...( relevantForTCO.length > 0 ? relevantForTCO : affordable ).map(m => calcTCO(m).fullAnnualTCO),
      ...[ 200 ]
    );

    const scored = affordable
      .map(m => ({ m, result: scoreMachine(m, qualityCeiling, bestAnnualTCO) }))
      .filter(x => x.result !== null && x.result !== undefined)
      .sort((a, b) => {
        const scoreDiff = b.result.score - a.result.score;
        if (scoreDiff !== 0) return scoreDiff;
        // Tie-breaker 1: lower annual TCO wins
        const tcoA = calcTCO(a.m).fullAnnualTCO;
        const tcoB = calcTCO(b.m).fullAnnualTCO;
        if (tcoA !== tcoB) return tcoA - tcoB;
        // Tie-breaker 2: higher eco/repair score wins
        return ((b.m.ecoRepairScore || 0) + (b.m.ecoScore || 0)) - ((a.m.ecoRepairScore || 0) + (a.m.ecoScore || 0));
      });

    // FIX08: Exclude machines scoring below 40% of the best raw score
    // But always guarantee at least 3 results — relax threshold if needed
    const bestRaw = scored.length > 0 ? scored[0].result.score : 0;
    let minThreshold = bestRaw * 0.40;
    let scoredFiltered = scored.filter(x => x.result.score >= minThreshold);
    // If fewer than 3 passed, lower threshold until we have 3 (or take all we have)
    if (scoredFiltered.length < 3 && scored.length >= 3) {
      scoredFiltered = scored.slice(0, 3);
    } else if (scoredFiltered.length < 3) {
      scoredFiltered = scored;
    }

    
  return scoredFiltered;
}

module.exports = { setAnswers, mapAirtableRecord, applyExtras, rank, calcTCO, getPrice, withTag, AFFILIATE_TAGS };
